window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-c984e9ff98e07e0e"]={"versions": [{"id": "FIG-c984e9ff98e07e0e", "releases": ["R24-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Anwendungsfalldiagramm (Use Case Diagram) im Kontext des AUTOSAR Classic Platform Mode Managements. Das Diagramm modelliert die Systemgrenze des Moduls <code>ECU State Management</code> (EcuM) sowie dessen Interaktionen mit umliegenden Akteuren auf Applikations-, Basissoftware- und Hardware-Ebene.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li>Systemgrenze: <code>ECU State Management</code>\n</li><li>Akteure:\n<ul class=\"fig-list\"><li><code>Application</code> (Software-Komponenten/Applikationsebene, links oben)\n</li><li><code>CDD</code> (Complex Device Driver, links unten)\n</li><li><code>ECU HW</code> (Steuergeräte-Hardware, rechts oben)\n</li><li><code>BSW</code> (Basissoftware-Module, rechts unten)\n</li></ul>\n</li><li>Anwendungsfälle (Use Cases):\n<ul class=\"fig-list\"><li><code>UC1: Start up ECU</code> (verbunden mit <code>ECU HW</code>)\n</li><li><code>UC2: Wake up ECU</code> (verbunden mit <code>ECU HW</code>)\n</li><li><code>UC3: Put ECU to sleep</code> (verbunden mit <code>BSW</code>)\n</li><li><code>UC4: Shutdown ECU</code> (verbunden mit <code>BSW</code>)\n</li><li><code>UC5: Keep ECU fully operational (RUN)</code> (gerichtet angesteuert von <code>Application</code>)\n</li><li><code>UC6: Prepare ECU for Shutdown (Post-RUN)</code> (gerichtet angesteuert von <code>Application</code>)\n</li><li><code>UC7: Schedule Wake-up Alarms</code> (verbunden mit <code>Application</code> und <code>CDD</code>)\n</li><li><code>UC8: Provide time since startup</code> (verbunden mit <code>Application</code> und <code>CDD</code>)\n</li><li><code>UC9: Activate Bootloader</code> (verbunden mit <code>Application</code>)\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Diagramm stellt funktionale Nutzungsszenarien statisch als Assoziationen zwischen Akteuren und Anwendungsfällen dar. Steuerungsflüsse gehen primär von der <code>Application</code> aus (gerichtete Anforderungen für RUN- und Post-RUN-Phasen sowie Bootloader-Aktivierung). Zustandsübergänge des Gesamtsystems bezüglich Startup und Wakeup interagieren direkt mit der <code>ECU HW</code>, während Sleep- und Shutdown-Abläufe mit der restlichen <code>BSW</code> interagieren. Timer- und Alarmdienste (<code>UC7</code>, <code>UC8</code>) stehen sowohl <code>Application</code> als auch <code>CDD</code> zur Verfügung.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Spezifiziert die High-Level-Anforderungen (Requirements) an das AUTOSAR ECU State Management. Die definierten Use Cases bilden die funktionale Grundlage für die Phasensteuerung (STARTUP, UP, SHUTDOWN, SLEEP) und Schnittstellenanforderungen des BSW-Moduls EcuM gegenüber Applikationen, Treibern (CDD), BSW-Modulen und Hardware-Events.</p>"}, {"id": "FIG-4f1482af8ef76f4c", "releases": ["R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Anwendungsfalldiagramm (Use Case Diagram) im Kontext des AUTOSAR Classic Platform Mode Managements. Das Diagramm modelliert die Systemgrenze des Moduls <code>ECU State Management</code> (EcuM) sowie dessen Interaktionen mit umliegenden Akteuren auf Applikations-, Basissoftware- und Hardware-Ebene.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li>Systemgrenze: <code>ECU State Management</code> (innerhalb des UML-Rahmens <code>Use Cases for ECU State Management</code>)\n</li><li>Akteure:\n<ul class=\"fig-list\"><li><code>Application</code> (links)\n</li><li><code>ECU HW</code> (rechts oben)\n</li><li><code>BSW</code> (rechts Mitte)\n</li><li><code>CDD</code> (rechts unten)\n</li></ul>\n</li><li>Anwendungsfälle (Use Cases):\n<ul class=\"fig-list\"><li><code>UC1: Start up ECU</code> (verbunden mit <code>ECU HW</code>)\n</li><li><code>UC2: Wake up ECU</code> (verbunden mit <code>ECU HW</code>)\n</li><li><code>UC3: Put ECU to sleep</code> (verbunden mit <code>BSW</code>)\n</li><li><code>UC4: Shutdown and reset ECU</code> (verbunden mit <code>BSW</code>)\n</li><li><code>UC5: Keep ECU fully operational (RUN state)</code> (verbunden mit <code>Application</code>)\n</li><li><code>UC6: Prepare ECU for Shutdown (POST_RUN State)</code> (verbunden mit <code>Application</code>)\n</li><li><code>UC7: Schedule Wake-up Alarms</code> (verbunden mit <code>Application</code> und <code>CDD</code>)\n</li><li><code>UC8: Provide time since startup</code> (verbunden mit <code>Application</code> und <code>CDD</code>)\n</li><li><code>UC9: Activate Bootloader</code> (verbunden mit <code>Application</code>)\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Diagramm stellt funktionale Nutzungsszenarien statisch über ungerichtete Assoziationen zwischen Akteuren und Anwendungsfällen dar. Die <code>Application</code> partizipiert an Betriebsphasen (<code>RUN state</code>, <code>POST_RUN State</code>), Alarm- und Zeitdiensten sowie der Bootloader-Aktivierung. Die <code>ECU HW</code> ist an Startup- und Wakeup-Abläufen beteiligt, während <code>BSW</code> an Sleep- und Shutdown-/Reset-Szenarien beteiligt ist. Der <code>CDD</code> greift auf Alarm- und Zeitdienste (<code>UC7</code>, <code>UC8</code>) zu.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Spezifiziert die High-Level-Anforderungen (Requirements) an das AUTOSAR ECU State Management. Die definierten Use Cases bilden die funktionale Grundlage für die Phasensteuerung (STARTUP, UP, SHUTDOWN, SLEEP) und Schnittstellenanforderungen des BSW-Moduls EcuM gegenüber Applikationen, Treibern (CDD), BSW-Modulen und Hardware-Events.</p>"}], "trans": [{"from": "FIG-c984e9ff98e07e0e", "to": "FIG-4f1482af8ef76f4c", "fr": "R24-11", "tr": "R25-11", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\"><li>Gesamtdiagramm: Neuzeichnung im Hochformat mit UML-Rahmen <code>Use Cases for ECU State Management</code>.\n</li><li>Akteure: <code>CDD</code> von der linken auf die rechte Seite verschoben; Assoziationen zu <code>UC7</code> und <code>UC8</code> verlaufen nun von rechts.\n</li><li>Pfeilspitzen: Gerichtete Assoziationen von <code>Application</code> zu <code>UC5</code> und <code>UC6</code> durch ungerichtete Linien ersetzt.\n</li><li>Beschriftung <code>UC4</code>: Von <code>UC4: Shutdown ECU</code> in <code>UC4: Shutdown and reset ECU</code> geändert.\n</li><li>Beschriftung <code>UC5</code>: Von <code>UC5: Keep ECU fully operational (RUN)</code> in <code>UC5: Keep ECU fully operational (RUN state)</code> geändert.\n</li><li>Beschriftung <code>UC6</code>: Von <code>UC6: Prepare ECU for Shutdown (Post-RUN)</code> in <code>UC6: Prepare ECU for Shutdown (POST_RUN State)</code> geändert.\n</li><li>Anordnung Use Cases: Vertikal in einer einzigen Spalte angeordnet (<code>UC5</code>, <code>UC6</code>, <code>UC1</code>, <code>UC2</code>, <code>UC3</code>, <code>UC4</code>, <code>UC7</code>, <code>UC8</code>, <code>UC9</code>).\n</li></ul>"}]};
